INSERT INTO `wp_posts` VALUES (1278,1,'2021-09-30 15:46:07','2021-09-30 15:46:07','<div data-colibri-id=\"26-c1\" class=\"style-412 style-local-26-c1 position-relative\">\n  <!---->\n  <div data-colibri-component=\"section\" data-colibri-id=\"26-c2\" id=\"about\" class=\"h-section h-section-global-spacing d-flex align-items-lg-center align-items-md-center align-items-center style-417 style-local-26-c2 position-relative\">\n    <!---->\n    <!---->\n    <div class=\"h-section-grid-container h-section-boxed-container\">\n      <!---->\n      <div data-colibri-id=\"26-c3\" class=\"h-row-container gutters-row-lg-0 gutters-row-md-0 gutters-row-0 gutters-row-v-lg-0 gutters-row-v-md-0 gutters-row-v-0 style-418 style-local-26-c3 position-relative\">\n        <!---->\n        <div class=\"h-row justify-content-lg-center justify-content-md-center justify-content-center align-items-lg-stretch align-items-md-stretch align-items-stretch gutters-col-lg-0 gutters-col-md-0 gutters-col-0 gutters-col-v-lg-0 gutters-col-v-md-0 gutters-col-v-0\">\n          <!---->\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-419-outer style-local-26-c4-outer\">\n            <div data-colibri-id=\"26-c4\" class=\"d-flex h-flex-basis h-column__inner h-ui-empty-state-container h-px-lg-0 h-px-md-0 h-px-0 v-inner-lg-0 v-inner-md-0 v-inner-0 style-419 style-local-26-c4 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100\">\n                <!---->\n              </div>\n            </div>\n          </div>\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-420-outer style-local-26-c5-outer\">\n            <div data-colibri-id=\"26-c5\" class=\"d-flex h-flex-basis h-column__inner h-px-lg-2 h-px-md-2 h-px-2 v-inner-lg-2 v-inner-md-2 v-inner-2 style-420 style-local-26-c5 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100 align-self-lg-start align-self-md-start align-self-start\">\n                <!---->\n                <div data-colibri-id=\"26-c6\" class=\"h-global-transition-all h-heading style-421 style-local-26-c6 position-relative h-element\">\n                  <!---->\n                  <div class=\"h-heading__outer style-421 style-local-26-c6\">\n                    <!---->\n                    <!---->\n                    <h4 class=\"\">About Us</h4>\n                  </div>\n                </div>\n                <div data-colibri-id=\"26-c7\" class=\"h-global-transition-all h-heading style-422 style-local-26-c7 position-relative h-element\">\n                  <!---->\n                  <div class=\"h-heading__outer style-422 style-local-26-c7\">\n                    <!---->\n                    <!---->\n                    <h2 class=\"\">We have highly skilled and experienced individuals ensuring that deadlines are met in an efficient, but cost effective manner</h2>\n                  </div>\n                </div>\n                <div data-colibri-id=\"26-c8\" class=\"h-text h-text-component style-423 style-local-26-c8 position-relative h-element\">\n                  <!---->\n                  <!---->\n                  <div class=\"\">\n                    <p>Glovtex Telecommunication Limited is an engineering company specializing in the development of Telco (Core/IN, Rollout and Maintenance) solutions for the GSM and wireless communication industry</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div data-colibri-component=\"section\" data-colibri-id=\"26-c9\" id=\"custom\" class=\"h-section h-section-global-spacing d-flex align-items-lg-center align-items-md-center align-items-center style-430 style-local-26-c9 position-relative\">\n    <!---->\n    <!---->\n    <div class=\"h-section-grid-container h-section-boxed-container\">\n      <div data-colibri-id=\"26-c13\" class=\"h-row-container gutters-row-lg-0 gutters-row-md-0 gutters-row-0 gutters-row-v-lg-0 gutters-row-v-md-0 gutters-row-v-0 style-434 style-local-26-c13 position-relative\">\n        <!---->\n        <div class=\"h-row justify-content-lg-center justify-content-md-center justify-content-center align-items-lg-stretch align-items-md-stretch align-items-stretch gutters-col-lg-0 gutters-col-md-0 gutters-col-0 gutters-col-v-lg-0 gutters-col-v-md-0 gutters-col-v-0\">\n          <!---->\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-435-outer style-local-26-c14-outer\">\n            <div data-colibri-id=\"26-c14\" class=\"d-flex h-flex-basis h-column__inner h-px-lg-2 h-px-md-2 h-px-2 v-inner-lg-2 v-inner-md-2 v-inner-2 style-435 style-local-26-c14 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100 align-self-lg-start align-self-md-start align-self-start\">\n                <!---->\n                <div data-colibri-id=\"26-c15\" class=\"h-global-transition-all h-heading style-436 style-local-26-c15 position-relative h-element\">\n                  <!---->\n                  <div class=\"h-heading__outer style-436 style-local-26-c15\">\n                    <!---->\n                    <!---->\n                    <h4 class=\"\">Our Mission</h4>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div data-colibri-id=\"26-c10\" class=\"h-row-container gutters-row-lg-2 gutters-row-md-2 gutters-row-0 gutters-row-v-lg-2 gutters-row-v-md-2 gutters-row-v-2 style-431 style-local-26-c10 position-relative\">\n        <!---->\n        <div class=\"h-row justify-content-lg-center justify-content-md-center justify-content-center align-items-lg-stretch align-items-md-stretch align-items-stretch gutters-col-lg-2 gutters-col-md-2 gutters-col-0 gutters-col-v-lg-2 gutters-col-v-md-2 gutters-col-v-2\">\n          <!---->\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-432-outer style-local-26-c11-outer\">\n            <div data-colibri-id=\"26-c11\" class=\"d-flex h-flex-basis h-column__inner h-px-lg-2 h-px-md-2 h-px-2 v-inner-lg-2 v-inner-md-2 v-inner-2 style-432 style-local-26-c11 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100 align-self-lg-start align-self-md-start align-self-start\">\n                <!---->\n                <div data-colibri-id=\"26-c12\" class=\"h-text h-text-component style-433 style-local-26-c12 position-relative h-element\">\n                  <!---->\n                  <!---->\n                  <div class=\"\">\n                    <p>Our mission is to earn, through dedication and hard work, a reputation of being the most reliable and efﬁcient organization in our chosen ﬁeld.</p>\n                    <p>We understand the importance of partnership and are committed to provide Global Solutions that maximize Business Telecommunication Assets; helping you to achieve your goals from basic deployment and roadmap, design and architecture,\n                      implementation and development to Operations &amp; Support</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div data-colibri-component=\"section\" data-colibri-id=\"26-c16\" id=\"features\" class=\"h-section h-section-global-spacing d-flex align-items-lg-center align-items-md-center align-items-center style-438 style-local-26-c16 position-relative\">\