INSERT INTO `wp_posts` VALUES (1344,1,'2021-09-30 16:16:01','2021-09-30 16:16:01','<div data-colibri-id=\"71-c1\" class=\"style-188 style-local-71-c1 position-relative\">\n  <!---->\n  <div data-colibri-component=\"section\" data-colibri-id=\"71-c2\" id=\"about\" class=\"h-section h-section-global-spacing d-flex align-items-lg-center align-items-md-center align-items-center style-198 style-local-71-c2 position-relative\">\n    <!---->\n    <!---->\n    <div class=\"h-section-grid-container h-section-boxed-container\">\n      <div data-colibri-id=\"71-c8\" class=\"h-row-container gutters-row-lg-2 gutters-row-md-2 gutters-row-0 gutters-row-v-lg-2 gutters-row-v-md-2 gutters-row-v-2 style-368 style-local-71-c8 position-relative\">\n        <!---->\n        <div class=\"h-row justify-content-lg-center justify-content-md-center justify-content-center align-items-lg-stretch align-items-md-stretch align-items-stretch gutters-col-lg-2 gutters-col-md-2 gutters-col-0 gutters-col-v-lg-2 gutters-col-v-md-2 gutters-col-v-2\">\n          <!---->\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-369-outer style-local-71-c9-outer\">\n            <div data-colibri-id=\"71-c9\" class=\"d-flex h-flex-basis h-column__inner h-px-lg-2 h-px-md-2 h-px-2 v-inner-lg-2 v-inner-md-2 v-inner-2 style-369 style-local-71-c9 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100 align-self-lg-start align-self-md-start align-self-start\">\n                <!---->\n                <div data-colibri-id=\"71-c10\" class=\"h-global-transition-all h-heading style-370 style-local-71-c10 position-relative h-element\">\n                  <!---->\n                  <div class=\"h-heading__outer style-370 style-local-71-c10\">\n                    <!---->\n                    <!---->\n                    <h4 class=\"\">We Help You Achieve the Right Solution</h4>\n                  </div>\n                </div>\n                <div data-colibri-id=\"71-c11\" class=\"h-text h-text-component style-371 style-local-71-c11 position-relative h-element\">\n                  <!---->\n                  <!---->\n                  <div class=\"\">\n                    <p>We have highly skilled and experienced individuals ensuring that deadlines are met in an efﬁcient, but cost effective manner</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n      <div data-colibri-id=\"71-c3\" class=\"h-row-container gutters-row-lg-0 gutters-row-md-2 gutters-row-2 gutters-row-v-lg-0 gutters-row-v-md-0 gutters-row-v-2 style-199 style-local-71-c3 position-relative\">\n        <!---->\n        <div class=\"h-row justify-content-lg-center justify-content-md-center justify-content-center align-items-lg-stretch align-items-md-stretch align-items-stretch gutters-col-lg-0 gutters-col-md-2 gutters-col-2 gutters-col-v-lg-0 gutters-col-v-md-0 gutters-col-v-2\">\n          <!---->\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-200-outer style-local-71-c4-outer\">\n            <div data-colibri-id=\"71-c4\" class=\"d-flex h-flex-basis h-column__inner h-ui-empty-state-container h-px-lg-2 h-px-md-2 h-px-0 v-inner-lg-2 v-inner-md-2 v-inner-0 style-200 style-local-71-c4 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100\">\n                <!---->\n              </div>\n            </div>\n          </div>\n          <div class=\"h-column h-column-container d-flex h-col-lg-auto h-col-md-auto h-col-auto style-201-outer style-local-71-c5-outer\">\n            <div data-colibri-id=\"71-c5\" class=\"d-flex h-flex-basis h-column__inner h-px-lg-3 h-px-md-3 h-px-3 v-inner-lg-3 v-inner-md-3 v-inner-3 style-201 style-local-71-c5 position-relative\">\n              <!---->\n              <!---->\n              <div class=\"w-100 h-y-container h-column__content h-column__v-align flex-basis-100 align-self-lg-center align-self-md-center align-self-center\">\n                <!---->\n                <div data-colibri-id=\"71-c6\" class=\"h-global-transition-all h-heading style-207 style-local-71-c6 position-relative h-element\">\n                  <!---->\n                  <div class=\"h-heading__outer style-207 style-local-71-c6\">\n                    <!---->\n                    <!---->\n                    <h4 class=\"\">The Company</h4>\n                  </div>\n                </div>\n                <div data-colibri-id=\"71-c7\" class=\"h-text h-text-component style-208 style-local-71-c7 position-relative h-element\">\n                  <!---->\n                  <!---->\n                  <div class=\"\">\n                    <p><strong>Glovtex Telecommunication Limited</strong> is an engineering company specializing in the development of Telco (Core/IN, Rollout and Maintenance) solutions for the GSM and wireless communication industry</p>\n                    <p>We are dedicated to offer a customer-centric approach to Technology projects, implementations and constructions in vivid contract to the more traditional approach</p>\n                    <p>Glovtex Telecommunication Limited serves several companies, all dominant players in their sectors: Telecom vendors, Service Providers, Mobile Operators, construction companies and other Information &amp; Communication businesses</p>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div data-colibri-component=\"section\" data-colibri-id=\"71-c12\" id=\"content1\" class=\"h-section h-section-global-spacing d-flex align-items-lg-center align-items-md-center align-items-center style-222 style-loc